<?php
/**
 * Live post grids, single posts and archives.
 *
 * The post grids on the static pages and in archive.php are printed from real
 * WordPress posts using each grid's ORIGINAL card markup (inc/post-widgets.json,
 * generated by tools/build_dynamic.py), so new posts appear wherever their
 * category puts them, in the original design.
 *
 * @package Coastal_Friends
 */

defined( 'ABSPATH' ) || exit;

/**
 * Grid definitions: widget id => template, query, paging.
 *
 * @return array
 */
function cf_widgets() {
	static $w = null;
	if ( null === $w ) {
		$w = json_decode( file_get_contents( get_template_directory() . '/inc/post-widgets.json' ), true ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
	}
	return $w;
}

/**
 * Page number for page grids (/page/2/, /gallery/2/ ...), set by the router.
 *
 * @return int
 */
function cf_paged() {
	return isset( $GLOBALS['cf_paged'] ) ? max( 1, (int) $GLOBALS['cf_paged'] ) : 1;
}

/**
 * Fill {{CF_ASSETS}} / {{CF_HOME}} in imported content.
 *
 * @param string $html Markup.
 * @return string
 */
function cf_fill_placeholders( $html ) {
	if ( false === strpos( (string) $html, '{{CF_' ) ) {
		return $html;
	}
	return strtr(
		$html,
		array(
			'{{CF_ASSETS}}' => cf_assets_url(),
			'{{CF_HOME}}'   => home_url( '/' ),
		)
	);
}
add_filter( 'the_content', 'cf_fill_placeholders', 1 );

/**
 * The query behind a grid.
 *
 * @param string $wid Widget id.
 * @return WP_Query
 */
function cf_widget_query( $wid ) {
	static $cache = array();
	if ( isset( $cache[ $wid ] ) ) {
		return $cache[ $wid ];
	}
	$cfg = cf_widgets()[ $wid ];
	if ( 'main' === $cfg['query'] ) {
		global $wp_query;
		return $cache[ $wid ] = $wp_query;
	}
	$args = array(
		'post_type'           => 'post',
		'post_status'         => 'publish',
		'posts_per_page'      => (int) $cfg['per_page'],
		'ignore_sticky_posts' => true,
		'paged'               => isset( $cfg['paged_key'] ) ? cf_paged() : 1,
	);
	if ( 'category' === $cfg['query'] ) {
		$args['category_name'] = $cfg['term'];
	}
	if ( ! empty( $cfg['order'] ) ) {
		$args['order'] = $cfg['order'];
	}
	return $cache[ $wid ] = new WP_Query( $args );
}

/**
 * Card thumbnail: the original <img> for imported posts, otherwise the featured image.
 *
 * @param string $size Image size the grid uses.
 * @return string
 */
function cf_card_thumb( $size = 'full' ) {
	$id = get_post_thumbnail_id();
	if ( ! $id ) {
		return '';
	}
	$orig = get_post_meta( get_the_ID(), '_cf_card_img', true );
	if ( $orig && (int) get_post_meta( get_the_ID(), '_cf_thumb_id', true ) === (int) $id ) {
		return cf_fill_placeholders( $orig );
	}
	return wp_get_attachment_image( $id, $size, false, array( 'loading' => 'lazy' ) );
}

/**
 * Featured image on single posts (original markup for imported posts).
 */
function cf_single_featured_image() {
	$id = get_post_thumbnail_id();
	if ( ! $id ) {
		return;
	}
	$orig = get_post_meta( get_the_ID(), '_cf_single_img', true );
	if ( $orig && (int) get_post_meta( get_the_ID(), '_cf_thumb_id', true ) === (int) $id ) {
		echo cf_fill_placeholders( $orig ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- theme-bundled markup.
		return;
	}
	echo wp_get_attachment_image( $id, 'full' );
}

/**
 * Whether a grid has posts on this page (Elementor leaves out an empty grid entirely).
 *
 * @param string $wid Widget id.
 * @return bool
 */
function cf_widget_has_posts( $wid ) {
	return cf_widget_query( $wid )->post_count > 0;
}

/**
 * Print a grid's cards.
 *
 * @param string $wid Widget id.
 */
function cf_posts_widget( $wid ) {
	$cfg = cf_widgets()[ $wid ];
	$q   = cf_widget_query( $wid );
	$out = '';
	while ( $q->have_posts() ) {
		$q->the_post();
		$cats  = get_the_category();
		$thumb = cf_card_thumb();
		$n     = (int) get_comments_number();
		$repl  = array(
			'{{POST_CLASSES}}' => esc_attr( implode( ' ', get_post_class() ) ),
			'{{THUMB_BLOCK}}'  => $thumb ? $cfg['thumb_block'] : '',
			'{{BADGE}}'        => $cats ? esc_html( $cats[0]->name ) : '',
			'{{TITLE}}'        => get_the_title(),
			'{{EXCERPT}}'      => $cfg['excerpt_words'] ? esc_html( wp_trim_words( get_the_excerpt(), (int) $cfg['excerpt_words'], '' ) ) : '',
			'{{DATE}}'         => esc_html( get_the_date() ),
			'{{COMMENTS}}'     => esc_html( 0 === $n ? __( 'No Comments', 'coastal-friends' ) : sprintf( _n( '%s Comment', '%s Comments', $n, 'coastal-friends' ), number_format_i18n( $n ) ) ),
		);
		$card = strtr( $cfg['template'], $repl );
		$out .= "\t\t\t\t" . strtr( $card, array( '{{PERMALINK}}' => esc_url( get_permalink() ), '{{THUMB}}' => $thumb ) ) . "\n";
	}
	if ( 'main' !== $cfg['query'] ) {
		wp_reset_postdata();
	}
	echo $out; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- escaped per field above.
}

/**
 * Current page and number of pages of a grid.
 *
 * @param string $wid Widget id.
 * @return array{0:int,1:int}
 */
function cf_widget_pages( $wid ) {
	$cfg = cf_widgets()[ $wid ];
	$q   = cf_widget_query( $wid );
	$cur = 'main' === $cfg['query'] ? max( 1, (int) get_query_var( 'paged' ) ) : cf_paged();
	return array( $cur, (int) $q->max_num_pages );
}

/**
 * URL of page $n of a grid.
 *
 * @param string $wid Widget id.
 * @param int    $n   Page number.
 * @return string
 */
function cf_widget_page_url( $wid, $n ) {
	$cfg = cf_widgets()[ $wid ];
	if ( 'main' === $cfg['query'] ) {
		return get_pagenum_link( $n );
	}
	$base = isset( $cfg['paged_key'] ) ? $cfg['paged_key'] : '';
	if ( '' === $base ) {
		return home_url( $n > 1 ? '/page/' . $n . '/' : '/' );
	}
	return home_url( '/' . $base . '/' . ( $n > 1 ? $n . '/' : '' ) );
}

/**
 * "Load more" anchor, as Elementor prints it.
 *
 * @param string $wid Widget id.
 */
function cf_posts_widget_anchor( $wid ) {
	list( $cur, $max ) = cf_widget_pages( $wid );
	if ( ! cf_widget_query( $wid )->post_count ) {
		return; // Elementor prints no anchor when the page has no posts.
	}
	printf(
		'<div class="e-load-more-anchor" data-page="%d" data-max-page="%d" data-next-page="%s"></div>',
		(int) $cur,
		(int) $max,
		esc_url( cf_widget_page_url( $wid, $cur + 1 ) )
	);
}

/**
 * Page numbers / previous-next links, as Elementor prints them.
 *
 * @param string $wid Widget id.
 */
function cf_posts_widget_nav( $wid ) {
	list( $cur, $max ) = cf_widget_pages( $wid );
	if ( $max < 2 ) {
		return;
	}
	$cfg = cf_widgets()[ $wid ];
	echo '<nav class="elementor-pagination" aria-label="' . esc_attr__( 'Pagination', 'coastal-friends' ) . '">' . "\n\t\t\t";
	if ( false !== strpos( $cfg['pagination_type'], 'prev_next' ) ) {
		echo $cur > 1 ? '<a class="page-numbers prev" href="' . esc_url( cf_widget_page_url( $wid, $cur - 1 ) ) . '">&laquo; ' . esc_html__( 'Previous', 'coastal-friends' ) . '</a>' : '<span class="page-numbers prev">&laquo; ' . esc_html__( 'Previous', 'coastal-friends' ) . '</span>';
		echo "\n";
	}
	if ( false !== strpos( $cfg['pagination_type'], 'numbers' ) ) {
		$links = array();
		for ( $i = 1; $i <= $max; $i++ ) {
			$label   = '<span class="elementor-screen-only">' . esc_html__( 'Page', 'coastal-friends' ) . '</span>' . $i;
			$links[] = $i === $cur ? '<span aria-current="page" class="page-numbers current">' . $label . '</span>' : '<a class="page-numbers" href="' . esc_url( cf_widget_page_url( $wid, $i ) ) . '">' . $label . '</a>';
		}
		echo implode( "\n", $links ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- built from escaped parts.
	}
	if ( false !== strpos( $cfg['pagination_type'], 'prev_next' ) ) {
		echo "\n";
		echo $cur < $max ? '<a class="page-numbers next" href="' . esc_url( cf_widget_page_url( $wid, $cur + 1 ) ) . '">' . esc_html__( 'Next', 'coastal-friends' ) . ' &raquo;</a>' : '<span class="page-numbers next">' . esc_html__( 'Next', 'coastal-friends' ) . ' &raquo;</span>';
	}
	echo "\t\t</nav>";
}
